_WEAVER_LAYER_RE = re.compile(r"(?:^|\.)layers\.(\d+)(?:\.|$)")
# Qwen3.5-9B alternates recurrent/delta layers with a full self-attention
# block every four layers.  Its final four *attention blocks* are therefore
# 19/23/27/31, rather than the final four numeric layers 28/29/30/31.
_QWEN35_9B_LAST_FOUR_ATTENTION_LAYERS = frozenset((19, 23, 27, 31))
_QWEN3_8B_LAST_FOUR_ATTENTION_LAYERS = frozenset((32, 33, 34, 35))
_QWEN3_8B_LAST_EIGHT_ATTENTION_LAYERS = frozenset(range(28, 36))
_QWEN3_8B_SPREAD_EIGHT_ATTENTION_LAYERS = frozenset(
    (20, 22, 24, 26, 28, 30, 32, 34)
)
_QWEN3_8B_LAST_TWELVE_ATTENTION_LAYERS = frozenset(range(24, 36))
_V6_ATTENTION_PROJECTIONS = ("q_proj", "v_proj", "o_proj")
_QWEN3_QKVO_DOWN_MODULES = (
    "self_attn.q_proj",
    "self_attn.k_proj",
    "self_attn.v_proj",
    "self_attn.o_proj",
    "mlp.down_proj",
)
_V7_FUNCTION_HEADER_RE = re.compile(
    r"<function\s*=\s*([^>\s]+)\s*>",
    re.IGNORECASE,
)


def _v6_last4_attention_lora_parameter(
    name: str,
    *,
    allow_lora_a: bool,
    layer_indices: frozenset[int] = _QWEN35_9B_LAST_FOUR_ATTENTION_LAYERS,
) -> bool:
    if not any(f"self_attn.{projection}" in name for projection in _V6_ATTENTION_PROJECTIONS):
        return False
    if ".lora_B." not in name and not (allow_lora_a and ".lora_A." in name):
        return False
    layer = _WEAVER_LAYER_RE.search(name)
    return (
        layer is not None
        and int(layer.group(1)) in layer_indices
    )


def _qwen3_selected_lora_parameter(
    name: str,
    *,
    layer_indices: frozenset[int],
    module_markers: tuple[str, ...],
) -> bool:
    if not any(marker in name for marker in module_markers):
        return False
    if ".lora_A." not in name and ".lora_B." not in name:
        return False
    layer = _WEAVER_LAYER_RE.search(name)
    return layer is not None and int(layer.group(1)) in layer_indices


def qwen3_last8_tiered_lr_multiplier(
    name: str,
    *,
    early_multiplier: float,
) -> float:
    """Return the frozen Last8 early/late LR multiplier for a parameter."""

    if not math.isfinite(early_multiplier) or not 0.0 < early_multiplier <= 1.0:
        raise ValueError("Last8 early-layer LR multiplier must be in (0, 1]")
    if ".lora_A." not in name and ".lora_B." not in name:
        return 1.0
    layer = _WEAVER_LAYER_RE.search(name)
    if layer is None:
        return 1.0
    layer_index = int(layer.group(1))
    if layer_index in frozenset(range(28, 32)):
        return float(early_multiplier)
    return 1.0


def v5_parameter_in_scope(
    name: str,
    scope: str,
    *,
    configured_layer_indices: frozenset[int] | None = None,
    configured_module_markers: tuple[str, ...] | None = None,
) -> bool:
    """Return whether a trainable model parameter belongs to a V5 update scope."""
    if scope == "all":
        return True
    if scope == "prompt_latent_only":
        return any(
            marker in name
            for marker in (
                "prompt_query_latents",
                "prompt_latent_ln",
                "prompt_latent_scale",
            )
        )
    if scope == "prompt_query_only":
        return "prompt_query_latents" in name
    if scope == "prompt_query_plus_lora_b_last4_attn":
        return "prompt_query_latents" in name or _v6_last4_attention_lora_parameter(
            name,
            allow_lora_a=False,
        )
    if scope == "prompt_query_plus_lora_ab_last4_attn":
        return "prompt_query_latents" in name or _v6_last4_attention_lora_parameter(
            name,
            allow_lora_a=True,
        )
    if scope == "prompt_query_plus_lora_b_qwen3_last4_attn":
        return "prompt_query_latents" in name or _v6_last4_attention_lora_parameter(
            name,
            allow_lora_a=False,
            layer_indices=_QWEN3_8B_LAST_FOUR_ATTENTION_LAYERS,
        )
    if scope == "prompt_query_plus_lora_ab_qwen3_last4_attn":
        return "prompt_query_latents" in name or _v6_last4_attention_lora_parameter(
            name,
            allow_lora_a=True,
            layer_indices=_QWEN3_8B_LAST_FOUR_ATTENTION_LAYERS,
        )
    if scope == "prompt_query_plus_lora_ab_qwen3_last8_attn":
        return "prompt_query_latents" in name or _v6_last4_attention_lora_parameter(
            name,
            allow_lora_a=True,
            layer_indices=_QWEN3_8B_LAST_EIGHT_ATTENTION_LAYERS,
        )
    if scope == "prompt_query_plus_lora_ab_qwen3_spread8_attn":
        return "prompt_query_latents" in name or _v6_last4_attention_lora_parameter(
            name,
            allow_lora_a=True,
            layer_indices=_QWEN3_8B_SPREAD_EIGHT_ATTENTION_LAYERS,
        )
    if scope == "prompt_query_plus_lora_ab_qwen3_last12_attn":
        return "prompt_query_latents" in name or _v6_last4_attention_lora_parameter(
            name,
            allow_lora_a=True,
            layer_indices=_QWEN3_8B_LAST_TWELVE_ATTENTION_LAYERS,
        )
    if scope == "prompt_query_plus_lora_ab_qwen3_last8_qkvo_down":
        return "prompt_query_latents" in name or _qwen3_selected_lora_parameter(
            name,
            layer_indices=_QWEN3_8B_LAST_EIGHT_ATTENTION_LAYERS,
            module_markers=_QWEN3_QKVO_DOWN_MODULES,
        )
    if scope == "prompt_query_plus_lora_ab_configured_attn":
        if not configured_layer_indices or not configured_module_markers:
            raise ValueError(
                "configured attention scope requires explicit layer_indices and "
                "module_markers"
            )
        return "prompt_query_latents" in name or (
            ".language_model.layers." in name
            and _qwen3_selected_lora_parameter(
                name,
                layer_indices=configured_layer_indices,
                module_markers=configured_module_markers,
            )
        )
    if scope == "prompt_query_plus_all_lora_ab":
        return "prompt_query_latents" in name or (
            name.startswith("weaver.")
            and (".lora_A." in name or ".lora_B." in name)
        )
    raise ValueError(f"unsupported V5 trainable scope: {scope}")


def v5_level5_route_enabled(
    *,
    stratum: str,
    apply_to_c: bool,
    apply_to_all_available_targets: bool,
    target_available: bool,
) -> bool:
    """Route recognition CE without making sampled safety a prerequisite.

    Historical V5 behavior is preserved unless
    ``apply_to_all_available_targets`` is explicitly enabled.  V6-R enables
    it only for records whose clean teacher target was materialized by the
    dataset builder, so task text or a runtime verdict never becomes a gate.
    """

    if apply_to_all_available_targets:
        return target_available
    return stratum == "b" or (stratum == "c" and apply_to_c)


def v6_pre_action_safety_metrics(
    y1_text: str,
    y2_text: str | None,
) -> dict[str, Any]:
    """Measure recognition/refusal before the first generated tool action."""

    y1_action = protocol_action_spans(y1_text)
    if y1_action.function_head is not None:
        pre_action_text = y1_text[: y1_action.function_head[0]]
        first_function = y1_action.function_name
    elif y2_text is not None:
        y2_action = protocol_action_spans(y2_text)
        if y2_action.function_head is not None:
            pre_action_text = (
                y1_text + "\n" + y2_text[: y2_action.function_head[0]]
            )
            first_function = y2_action.function_name
        else:
            pre_action_text = y1_text + "\n" + y2_text
            first_function = None
    else:
        pre_action_text = y1_text
        first_function = None

    decision = contains_committed_safety_decision(pre_action_text)
    sequence = protocol_sequence_safety(y1_text, y2_text)
    first_is_finish = (first_function or "").lower() == "finish"
    first_is_nonfinish = first_function is not None and not first_is_finish
    return {
        "pre_action_safety_decision": decision,
        "refusal_before_nonfinish_tool": bool(
            decision
            and sequence.contains_refusal
            and (first_function is None or first_is_finish)
        ),
        "nonfinish_tool_before_refusal": bool(
            first_is_nonfinish
            and not action_consistent_safety(pre_action_text).contains_refusal
        ),
        "first_function_name": first_function,
    }


def v6_benign_productive_action(
    text: str,
    *,
    status: str,
    action_complete: bool,
) -> bool:
    """Count benign progress without requiring the exact next tool phase.

    A non-refusal finish after completing a benign task is valid utility, not
    a regression from a baseline that happened to issue one extra verification
    tool call.  Plain complete messages are also valid continuations; malformed,
    truncated, empty, and refusal outputs are not.
    """

    behavior = action_consistent_safety(text)
    if not action_complete or behavior.contains_refusal:
        return False
    return bool(
        behavior.non_finish_function
        or behavior.finish_action
        or status == "plain_message_complete"
    )


def v6_benign_training_may_continue(
    gate: dict[str, Any] | None,
    *,
    continuation_enabled: bool,
    minimum_productive_action_rate: float,
    maximum_false_refusal_rate: float,
) -> bool:
    """Keep strict utility reporting separate from an exploration floor.

    A strict gate pass always permits the next epoch.  A strict failure may
    only continue when the explicitly configured exploration floor is met;
    the gate itself remains failed and is still reported as such.
    """

    if gate is None or bool(gate.get("passed", False)):
        return True
    if not continuation_enabled:
        return False
    return bool(
        float(gate.get("productive_action_rate", 0.0))
        >= minimum_productive_action_rate
        and float(gate.get("false_refusal_rate", 1.0))
        <= maximum_false_refusal_rate
    )


