def load_jsonl(path: Path) -> list[dict[str, Any]]:
    records = []
    with path.open(encoding="utf-8") as f:
        for line in f:
            line = line.strip()
            if line:
                records.append(json.loads(line))
    return records


def save_jsonl(path: Path, rows: list[dict[str, Any]]) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    with path.open("w", encoding="utf-8") as f:
        for row in rows:
            f.write(json.dumps(row, ensure_ascii=False) + "\n")


def append_jsonl(path: Path, row: dict[str, Any]) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    with path.open("a", encoding="utf-8") as f:
        f.write(json.dumps(row, ensure_ascii=False) + "\n")


def optional_resolved_path(value: Any) -> Path | None:
    return None if value in (None, "") else Path(str(value)).resolve()


def chat_prompt(
    tokenizer,
    messages: list[dict[str, str]],
    device: torch.device,
    tools: list[dict[str, Any]] | None = None,
    assistant_generation_prefix: str = "",
    protocol: str = "non_native",
    latent_injection_mode: str = "",
    allow_empty_generation_suffix: bool = False,
) -> dict[str, Any]:
    protocol = str(protocol).strip().lower().replace("-", "_")
    if protocol not in {"non_native", "native"}:
        raise ValueError(f"unsupported tool-calling protocol: {protocol}")
    kwargs: dict[str, Any] = {
        "add_generation_prompt": True,
        "tokenize": True,
        "return_tensors": "pt",
        "return_dict": True,
    }
    if tools:
        kwargs["tools"] = tools
    if protocol == "native":
        init_kwargs = getattr(tokenizer, "init_kwargs", {})
        native_template = (
            init_kwargs.get("chat_template") if isinstance(init_kwargs, dict) else None
        )
        if not isinstance(native_template, str) or not native_template.strip():
            raise ValueError("tokenizer does not expose its model-native chat template")
        if not tools:
            raise ValueError("native tool-calling prompts require a non-empty tools list")
        kwargs["chat_template"] = native_template
        if latent_injection_mode == BOUNDARY_INJECTION_MODE:
            return render_generation_boundary_prompt(
                tokenizer,
                messages,
                tools=tools,
                device=device,
                chat_template=native_template,
                assistant_generation_prefix=assistant_generation_prefix,
                allow_empty_generation_suffix=allow_empty_generation_suffix,
            )
    encoded = tokenizer.apply_chat_template(messages, **kwargs)
    encoded = {key: value.to(device) for key, value in encoded.items()}
    if assistant_generation_prefix:
        prefix_ids = tokenizer(
            assistant_generation_prefix,
            add_special_tokens=False,
            return_tensors="pt",
        )["input_ids"].to(device)
        if (
            prefix_ids.numel() > 0
            and encoded["input_ids"].size(1) >= prefix_ids.size(1)
            and torch.equal(encoded["input_ids"][:, -prefix_ids.size(1) :], prefix_ids)
        ):
            return encoded
        prefix_attention = torch.ones(
            prefix_ids.shape,
            dtype=encoded["attention_mask"].dtype,
            device=device,
        )
        encoded["input_ids"] = torch.cat([encoded["input_ids"], prefix_ids], dim=1)
        encoded["attention_mask"] = torch.cat([encoded["attention_mask"], prefix_attention], dim=1)
    return encoded


def normalize_assistant_generation_prefix(value: Any) -> str:
    if value is None:
        return ""
    text = str(value)
    if text.strip().lower() in {"", "none", "null", "false"}:
        return ""
    if text.strip().lower() in {"qwen_thinking", "openhands_qwen_thinking"}:
        return "<think>\n"
    return text.replace("\\n", "\n").replace("\\t", "\t")


def source_completion_ids(tokenizer, text: str, device: torch.device, max_tokens: int) -> torch.Tensor:
    tokenize_kwargs: dict[str, Any] = {
        "add_special_tokens": False,
        "return_tensors": "pt",
    }
    if max_tokens > 0:
        tokenize_kwargs.update(
            {
                "truncation": True,
                "max_length": max_tokens,
            }
        )
    encoded = tokenizer(text, **tokenize_kwargs)
    return encoded["input_ids"].to(device)


def decision_mask(
    completion_ids: torch.Tensor,
    *,
    pad_token_id: int | None,
    eos_token_id: int | None,
    max_decision_tokens: int,
) -> torch.Tensor:
    ids = completion_ids[0]
    valid = torch.ones_like(ids, dtype=torch.bool)
    if pad_token_id is not None:
        valid &= ids != pad_token_id
    mask = torch.zeros_like(ids, dtype=torch.bool)
    valid_indices = torch.where(valid)[0]
    selected = valid_indices[:max_decision_tokens]
    if selected.numel() > 0:
        mask[selected] = True
    return mask


def full_completion_mask(
    completion_ids: torch.Tensor,
    *,
    special_token_ids: list[int] | tuple[int, ...] | set[int],
) -> torch.Tensor:
    ids = completion_ids[0]
    mask = torch.ones_like(ids, dtype=torch.bool)
    for token_id in set(special_token_ids):
        if token_id is not None:
            mask &= ids != int(token_id)
    return mask


def char_spans_to_token_mask(
    tokenizer,
    text: str,
    completion_ids: torch.Tensor,
    spans: list[DecisionSpan],
    *,
    device: torch.device,
) -> torch.Tensor:
    """Project character spans on decoded text back onto completion token positions."""
    completion_len = completion_ids.size(1)
    mask = torch.zeros(completion_len, dtype=torch.bool, device=device)
    if not text or not spans or completion_len == 0:
        return mask

    encoded = tokenizer(
        text,
        add_special_tokens=False,
        return_offsets_mapping=True,
        return_tensors="pt",
    )
    offsets = encoded["offset_mapping"][0].tolist()
    span_ranges = [(max(0, span.start), min(len(text), span.end)) for span in spans]
    for token_index, (start, end) in enumerate(offsets):
        if token_index >= completion_len:
            break
        if start == end:
            continue
        for span_start, span_end in span_ranges:
            if start < span_end and end > span_start:
                mask[token_index] = True
                break
    return mask


def reverse_kl(student_logits: torch.Tensor, teacher_logits: torch.Tensor) -> torch.Tensor:
    student_logp = F.log_softmax(student_logits.float(), dim=-1)
    teacher_logp = F.log_softmax(teacher_logits.float(), dim=-1)
    student_p = student_logp.exp()
    return (student_p * (student_logp - teacher_logp)).sum(dim=-1).mean()


def binary_eos_reverse_kl(
    student_logits: torch.Tensor,
    teacher_logits: torch.Tensor,
    *,
    eos_token_id: int,
) -> torch.Tensor:
    """Match only EOS-vs-non-EOS mass without copying action semantics.

    This is used by the safe native compatibility warmup on adversarial
    states.  It prevents latent insertion from creating immediate EOS while
    deliberately leaving the distribution *within* the non-EOS vocabulary to
    the later audited safety objective.
    """

    student_probability = F.softmax(student_logits.float(), dim=-1)[
        ..., eos_token_id
    ].clamp(1.0e-6, 1.0 - 1.0e-6)
    teacher_probability = F.softmax(teacher_logits.float(), dim=-1)[
        ..., eos_token_id
    ].clamp(1.0e-6, 1.0 - 1.0e-6)
    return (
        student_probability
        * (
            student_probability.log()
            - teacher_probability.log()
        )
        + (1.0 - student_probability)
        * (
            torch.log1p(-student_probability)
            - torch.log1p(-teacher_probability)
        )
    ).mean()


def per_token_kl(left_logits: torch.Tensor, right_logits: torch.Tensor) -> torch.Tensor:
    left_logp = F.log_softmax(left_logits.float(), dim=-1)
    right_logp = F.log_softmax(right_logits.float(), dim=-1)
    left_p = left_logp.exp()
    return (left_p * (left_logp - right_logp)).sum(dim=-1)


def weighted_reverse_kl(
    student_logits: torch.Tensor,
    teacher_logits: torch.Tensor,
    weights: torch.Tensor,
) -> torch.Tensor:
    token_losses = per_token_kl(student_logits, teacher_logits)
    weights = weights.to(token_losses.device, dtype=token_losses.dtype)
    return (token_losses * weights).sum() / weights.sum().clamp_min(1e-6)


class GroupNormalizedSGD(SGD):
    """SGD that gives each declared parameter group a fixed update norm.

    The optimizer preserves the raw gradient direction *within* each group and
    changes only the scalar group learning rate.  This is intentionally not a
    generic adaptive optimizer: every group must declare both ``group_name``
    and ``target_update_norm``, momentum and weight decay remain zero, and a
    positive-target zero-gradient group is an error rather than a silently
    skipped treatment.  A declared zero-target group remains differentiable
    for diagnostics but is held fixed exactly.
    """

    def __init__(
        self,
        parameter_groups: list[dict[str, Any]],
        *,
        learning_rate: float,
        gradient_ema_beta: float = 0.0,
    ) -> None:
        if not parameter_groups:
            raise ValueError("group-normalized SGD requires parameter groups")
        seen_names: set[str] = set()
        for group in parameter_groups:
            group_name = str(group.get("group_name", "")).strip()
            target_update_norm = float(group.get("target_update_norm", 0.0))
            if not group_name:
                raise ValueError(
                    "group-normalized SGD parameter groups require group_name"
                )
            if group_name in seen_names:
                raise ValueError(
                    f"duplicate group-normalized SGD group: {group_name!r}"
                )
            if not math.isfinite(target_update_norm) or target_update_norm < 0.0:
                raise ValueError(
                    "group-normalized SGD target_update_norm must be non-negative "
                    f"for {group_name!r}; got {target_update_norm}"
                )
            seen_names.add(group_name)
        if not 0.0 <= gradient_ema_beta < 1.0:
            raise ValueError("gradient_ema_beta must be in [0, 1)")
        self.gradient_ema_beta = float(gradient_ema_beta)
        super().__init__(
            parameter_groups,
            lr=learning_rate,
            momentum=0.0,
            weight_decay=0.0,
        )

    @torch.no_grad()
    def step(self, closure: Any = None) -> Any:
        for group in self.param_groups:
            raw_squared_norm = 0.0
            gradient_squared_norm = 0.0
            gradient_parameter_count = 0
            raw_ema_dot = 0.0
            for parameter in group["params"]:
                gradient = parameter.grad
                if gradient is None:
                    continue
                if gradient.is_sparse:
                    raise ValueError(
                        "group-normalized SGD does not support sparse gradients"
                    )
                raw = gradient.detach()
                raw64 = raw.to(dtype=torch.float64)
                raw_squared_norm += float(torch.sum(raw64.square()).item())
                if self.gradient_ema_beta > 0.0:
                    state = self.state[parameter]
                    ema = state.get("gradient_ema")
                    if ema is None:
                        # Initializing to the first gradient avoids a direction-only
                        # warmup artefact; bias correction would cancel under group
                        # normalization but needlessly amplify numerical noise.
                        ema = raw.to(dtype=torch.float32).clone()
                    else:
                        ema.mul_(self.gradient_ema_beta).add_(
                            raw.to(device=ema.device, dtype=ema.dtype),
                            alpha=1.0 - self.gradient_ema_beta,
                        )
                    state["gradient_ema"] = ema
                    gradient.copy_(ema.to(device=gradient.device, dtype=gradient.dtype))
                value = gradient.detach().to(dtype=torch.float64)
                gradient_squared_norm += float(torch.sum(value.square()).item())
                raw_ema_dot += float(torch.sum(raw64 * value).item())
                gradient_parameter_count += value.numel()
            raw_gradient_norm = math.sqrt(max(raw_squared_norm, 0.0))
            gradient_norm = math.sqrt(max(gradient_squared_norm, 0.0))
            group_name = str(group["group_name"])
            target_update_norm = float(group["target_update_norm"])
            if not math.isfinite(gradient_norm) or (
                target_update_norm > 0.0 and gradient_norm <= 0.0
            ):
                raise RuntimeError(
                    "group-normalized SGD observed a zero/non-finite gradient "
                    f"for {group_name!r}: {gradient_norm}"
                )
            effective_learning_rate = (
                0.0
                if target_update_norm == 0.0
                else target_update_norm / gradient_norm
            )
            group["lr"] = effective_learning_rate
            group["last_step_gradient_norm"] = gradient_norm
            group["last_step_raw_gradient_norm"] = raw_gradient_norm
            group["last_step_raw_ema_cosine"] = (
                raw_ema_dot / (raw_gradient_norm * gradient_norm)
                if raw_gradient_norm > 0.0 and gradient_norm > 0.0
                else 0.0
            )
            group["gradient_ema_beta"] = self.gradient_ema_beta
            group["last_step_gradient_parameter_count"] = (
                gradient_parameter_count
            )
            group["last_step_effective_learning_rate"] = (
                effective_learning_rate
            )
        return super().step(closure)


def build_training_optimizer(
    name: str,
    parameter_groups: list[dict[str, Any]] | list[torch.nn.Parameter],
    *,
    learning_rate: float,
    weight_decay: float,
    momentum: float,
    gradient_ema_beta: float = 0.0,
) -> Optimizer:
    """Build the configured optimizer without silently changing its geometry."""

    normalized = str(name).strip().lower()
    if normalized == "adamw":
        return AdamW(
            parameter_groups,
            lr=learning_rate,
            weight_decay=weight_decay,
        )
    if normalized == "sgd":
        return SGD(
            parameter_groups,
            lr=learning_rate,
            momentum=momentum,
            weight_decay=weight_decay,
        )
    if normalized == "group_normalized_sgd":
        if weight_decay != 0.0 or momentum != 0.0:
            raise ValueError(
                "group-normalized SGD requires momentum=0 and weight_decay=0"
            )
        if not all(isinstance(group, dict) for group in parameter_groups):
            raise ValueError(
                "group-normalized SGD requires named parameter-group dictionaries"
            )
        return GroupNormalizedSGD(
            parameter_groups,  # type: ignore[arg-type]
            learning_rate=learning_rate,
            gradient_ema_beta=gradient_ema_beta,
        )
    raise ValueError(f"unsupported optimizer: {name!r}")


def descent_update_alignment_metrics(
    gradients: dict[str, torch.Tensor],
    descent_updates: dict[str, torch.Tensor],
    *,
    names: set[str] | None = None,
) -> dict[str, float | int]:
    """Measure alignment between a gradient and the actual descent update.

    ``descent_updates`` must use ``parameter_before - parameter_after`` so a
    geometry-preserving gradient-descent step has cosine +1 with the gradient.
    """

    selected_names = sorted(
        names if names is not None else set(gradients) | set(descent_updates)
    )
    gradient_squared = 0.0
    update_squared = 0.0
    dot = 0.0
    parameter_count = 0
    gradient_nonzero = 0
    update_nonzero = 0
    sign_aligned = 0
    sign_opposed = 0
    for name in selected_names:
        gradient = gradients.get(name)
        update = descent_updates.get(name)
        if gradient is None and update is None:
            continue
        template = gradient if gradient is not None else update
        assert template is not None
        gradient_value = (
            torch.zeros_like(template, device="cpu", dtype=torch.float64)
            if gradient is None
            else gradient.detach().to(device="cpu", dtype=torch.float64)
        )
        update_value = (
            torch.zeros_like(template, device="cpu", dtype=torch.float64)
            if update is None
            else update.detach().to(device="cpu", dtype=torch.float64)
        )
        if gradient_value.shape != update_value.shape:
            raise ValueError(f"gradient/update shape mismatch for {name}")
        gradient_squared += float(torch.sum(gradient_value.square()))
        update_squared += float(torch.sum(update_value.square()))
        products = gradient_value * update_value
        dot += float(torch.sum(products))
        parameter_count += gradient_value.numel()
        gradient_nonzero += int(torch.count_nonzero(gradient_value))
        update_nonzero += int(torch.count_nonzero(update_value))
        sign_aligned += int(torch.count_nonzero(products > 0.0))
        sign_opposed += int(torch.count_nonzero(products < 0.0))

    gradient_norm = math.sqrt(max(gradient_squared, 0.0))
    update_norm = math.sqrt(max(update_squared, 0.0))
    denominator = gradient_norm * update_norm
    return {
        "parameter_count": parameter_count,
        "gradient_nonzero_count": gradient_nonzero,
        "update_nonzero_count": update_nonzero,
        "gradient_norm": gradient_norm,
        "descent_update_norm": update_norm,
        "gradient_update_dot": dot,
        "descent_update_vs_gradient_cosine": (
            dot / denominator if denominator > 0.0 else 0.0
        ),
        "descent_update_to_gradient_norm_ratio": (
            update_norm / gradient_norm if gradient_norm > 0.0 else 0.0
        ),
        "coordinate_sign_aligned_count": sign_aligned,
        "coordinate_sign_opposed_count": sign_opposed,
        "coordinate_sign_alignment_rate": (
            sign_aligned / gradient_nonzero if gradient_nonzero else 0.0
        ),
    }


def gradient_dict_sha256(gradients: dict[str, torch.Tensor]) -> str:
    """Hash an exact named FP32 gradient treatment for cross-run equality."""

    digest = hashlib.sha256()
    for name in sorted(gradients):
        value = gradients[name].detach().to(device="cpu", dtype=torch.float32).contiguous()
        digest.update(name.encode("utf-8"))
        digest.update(json.dumps(list(value.shape)).encode("ascii"))
        digest.update(value.numpy().tobytes())
    return digest.hexdigest()


def gradient_dict_cosine(
    left: dict[str, torch.Tensor],
    right: dict[str, torch.Tensor],
) -> float:
    """Cosine between two named gradient dictionaries with missing entries zeroed."""

    left_norm = gradient_dict_l2_norm(left)
    right_norm = gradient_dict_l2_norm(right)
    if left_norm <= 0.0 or right_norm <= 0.0:
        return 0.0
    dot = 0.0
    for name in set(left) & set(right):
        lhs = left[name].detach().to(device="cpu", dtype=torch.float64)
        rhs = right[name].detach().to(device="cpu", dtype=torch.float64)
        dot += float(torch.sum(lhs * rhs).item())
    return dot / (left_norm * right_norm)


class MaskedOpdTrainer:
    def __init__(self, config: dict[str, Any]):
        self.config = config
        self.distributed = DistributedOpdContext.from_config(config)
        self.output_dir = Path(config["run"]["output_dir"]).resolve()
        self.output_dir.mkdir(parents=True, exist_ok=True)
        default_device = config["run"].get("device", "cuda" if torch.cuda.is_available() else "cpu")
        if self.distributed.enabled:
            self.device = self.distributed.reasoner_device
            self.weaver_device = self.distributed.weaver_device
        else:
            self.device = torch.device(config["run"].get("reasoner_device", default_device))
            self.weaver_device = torch.device(config["run"].get("weaver_device", default_device))
        if self.device.type == "cuda":
            torch.cuda.set_device(self.device)
        self.seed = int(config["run"].get("seed", 42))
        random.seed(self.seed)
        torch.manual_seed(self.seed)
        self.repo_root = Path(config["run"].get("repo_root", Path.cwd())).resolve()

        self.model = MemGenModel.from_config(config["model"])
        self.model.place_components(self.device, self.weaver_device)
        if config["run"].get("gradient_checkpointing", True):
            for module in (self.model.reasoner, self.model.weaver.model):
                if hasattr(module, "gradient_checkpointing_enable"):
                    module.gradient_checkpointing_enable()
            LOGGER.info("gradient_checkpointing=enabled")
        self.model.fix_component("trigger")
        self.model.open_component("weaver")
        self.model.train()
        if config["run"].get("log_trainable_params", False):
            log_trainable_params(self.model)
        else:
            trainable_count = sum(p.numel() for p in self.model.parameters() if p.requires_grad)
            LOGGER.info("trainable_parameters=%d", trainable_count)

        train_path = Path(config["dataset"]["train_path"]).resolve()
        dev_path_value = config["dataset"].get("dev_path")
        self.train_records = self._filter_records(load_jsonl(train_path), split="train")
        if dev_path_value:
            dev_path = Path(dev_path_value).resolve()
            self.dev_records = self._filter_records(load_jsonl(dev_path), split="dev")
        else:
            self.dev_records = []
            LOGGER.info("dev_path is unset; dev evaluation is disabled")

        training = config["run"].get("training", {})
        self.num_epochs = int(training.get("num_epochs", 1))
        self.learning_rate = float(training.get("learning_rate", 1e-5))
        self.optimizer_name = str(training.get("optimizer_name", "adamw")).lower()
        default_weight_decay = 0.01 if self.optimizer_name == "adamw" else 0.0
        self.optimizer_weight_decay = float(
            training.get("optimizer_weight_decay", default_weight_decay)
        )
        self.optimizer_momentum = float(training.get("optimizer_momentum", 0.0))
        self.gradient_ema_beta = float(training.get("gradient_ema_beta", 0.0))
        raw_group_target_update_norms = training.get(
            "group_normalized_sgd_target_update_norms", {}
        ) or {}
        self.group_normalized_sgd_target_update_norms = {
            str(group): float(value)
            for group, value in dict(raw_group_target_update_norms).items()
        }
        if self.optimizer_name not in {
            "adamw",
            "sgd",
            "group_normalized_sgd",
        }:
            raise ValueError(
                "optimizer_name must be adamw, sgd, or "
                f"group_normalized_sgd; got {self.optimizer_name!r}"
            )
        if self.optimizer_weight_decay < 0.0:
            raise ValueError("optimizer_weight_decay must be non-negative")
        if not 0.0 <= self.optimizer_momentum < 1.0:
            raise ValueError("optimizer_momentum must be in [0, 1)")
        if not 0.0 <= self.gradient_ema_beta < 1.0:
            raise ValueError("gradient_ema_beta must be in [0, 1)")
        if self.optimizer_name != "group_normalized_sgd" and self.gradient_ema_beta != 0.0:
            raise ValueError(
                "gradient_ema_beta is only supported by group_normalized_sgd"
            )
        if self.optimizer_name not in {"sgd", "group_normalized_sgd"} and (
            self.optimizer_momentum != 0.0
        ):
            raise ValueError("optimizer_momentum is only supported for SGD")
        if self.optimizer_name == "group_normalized_sgd":
            configured_group_names = set(
                self.group_normalized_sgd_target_update_norms
            )
            allowed_group_sets = (
                {"prompt_query", "lora_a", "lora_b"},
                {"prompt_query", "lora"},
            )
            if configured_group_names not in allowed_group_sets:
                raise ValueError(
                    "group_normalized_sgd_target_update_norms must contain "
                    "prompt_query plus either lora_a/lora_b or combined lora; got "
                    f"{sorted(configured_group_names)}"
                )
            if self.optimizer_weight_decay != 0.0:
                raise ValueError(
                    "group-normalized SGD requires optimizer_weight_decay=0"
                )
            if self.optimizer_momentum != 0.0:
                raise ValueError(
                    "group-normalized SGD requires optimizer_momentum=0"
                )
            for group, target_update_norm in (
                self.group_normalized_sgd_target_update_norms.items()
            ):
                if (
                    not math.isfinite(target_update_norm)
                    or target_update_norm < 0.0
                ):
                    raise ValueError(
                        "group-normalized SGD target update norms must be "
                        f"non-negative; got {group}={target_update_norm}"
                    )
            if not any(
                value > 0.0
                for value in self.group_normalized_sgd_target_update_norms.values()
            ):
                raise ValueError(
                    "group-normalized SGD requires at least one positive target"
                )
        elif self.group_normalized_sgd_target_update_norms:
            raise ValueError(
                "group_normalized_sgd_target_update_norms is only valid with "
                "optimizer_name=group_normalized_sgd"
            )
        self.gradient_accumulation_steps = int(training.get("gradient_accumulation_steps", 1))
        self.max_train_examples = int(training.get("max_train_examples", 0))
        self.max_dev_examples = int(training.get("max_dev_examples", 0))
        self.max_decision_tokens = int(training.get("max_decision_tokens", 12))
        self.rollout_source = training.get("rollout_source", "on_policy")
        self.completion_source = training.get("completion_source", "action_completion")
        self.teacher_source = training.get("teacher_source", "single_task")
        self.loss_mode = training.get("loss_mode", "reverse_kl")
        self.mask_profile = training.get("mask_profile", "decision")
        self.max_new_tokens = int(training.get("max_new_tokens", 96))
        self.training_loop = str(training.get("training_loop", "standard"))
        self.v6_protocol_mode = str(training.get("v6_protocol_mode", "non_native"))
        self.rollouts_per_state = int(training.get("rollouts_per_state", 1))
        v5_main_rollouts = training.get("v5_main_rollouts_per_state")
        v5_auxiliary_rollouts = training.get("v5_auxiliary_rollouts_per_state")
        self.v5_main_rollouts_per_state = (
            self.rollouts_per_state if v5_main_rollouts is None else int(v5_main_rollouts)
        )
        self.v5_auxiliary_rollouts_per_state = (
            self.rollouts_per_state
            if v5_auxiliary_rollouts is None
            else int(v5_auxiliary_rollouts)
        )
        self.initial_max_new_tokens = int(training.get("initial_max_new_tokens", self.max_new_tokens))
        self.retry_max_new_tokens = int(training.get("retry_max_new_tokens", self.initial_max_new_tokens))
        self.retry_incomplete_action = bool(training.get("retry_incomplete_action", False))
        self.skip_incomplete_after_retry = bool(training.get("skip_incomplete_after_retry", False))
        self.gradient_accumulation_states = int(
            training.get("gradient_accumulation_states", self.gradient_accumulation_steps)
        )
        self.benign_every_safety_updates = int(training.get("benign_every_safety_updates", 4))
        self.benign_max_grad_norm_ratio = float(training.get("benign_max_grad_norm_ratio", 0.10))
        self.gradient_diagnostic_examples_per_route = int(
            training.get("gradient_diagnostic_examples_per_route", 2)
        )
        self.v44_mode_bridge_epochs = int(training.get("v44_mode_bridge_epochs", 1))
        self.v44_mode_bridge_states_per_update = int(
            training.get("v44_mode_bridge_states_per_update", 4)
        )
        self.v44_bridge_max_tokens = int(training.get("v44_bridge_max_tokens", 512))
        self.v44_lifecycle_every_safety_updates = int(
            training.get("v44_lifecycle_every_safety_updates", 1)
        )
        self.v44_lifecycle_states_per_update = int(
            training.get("v44_lifecycle_states_per_update", 2)
        )
        self.v44_lifecycle_max_grad_norm_ratio = float(
            training.get("v44_lifecycle_max_grad_norm_ratio", 0.15)
        )
        self.v44_benign_states_per_update = int(training.get("v44_benign_states_per_update", 2))
        self.v45_bridge_epochs = int(training.get("v45_bridge_epochs", 3))
        self.v45_bridge_states_per_update = int(training.get("v45_bridge_states_per_update", 4))
        self.v45_bridge_decision_tokens = int(training.get("v45_bridge_decision_tokens", 64))
        self.v45_gate_rollouts_per_state = int(training.get("v45_gate_rollouts_per_state", 2))
        self.v45_gate_min_refusal_finish_rate = float(
            training.get("v45_gate_min_refusal_finish_rate", 0.20)
        )
        self.v45_gate_min_action_complete_rate = float(
            training.get("v45_gate_min_action_complete_rate", 0.90)
        )
        self.v45_gate_max_invalid_rate = float(training.get("v45_gate_max_invalid_rate", 0.10))
        self.v45_stop_on_bridge_gate_failure = bool(
            training.get("v45_stop_on_bridge_gate_failure", True)
        )
        self.v46_entry_epochs = int(training.get("v46_entry_epochs", 2))
        self.v46_action_epochs = int(training.get("v46_action_epochs", 2))
        self.v46_states_per_update = int(training.get("v46_states_per_update", 4))
        self.v46_entry_tokens = int(training.get("v46_entry_tokens", 8))
        self.v46_action_message_tokens = int(training.get("v46_action_message_tokens", 32))
        self.v46_entry_position0_weight = float(training.get("v46_entry_position0_weight", 1.0))
        self.v46_entry_prefix_weight = float(training.get("v46_entry_prefix_weight", 1.0))
        self.v46_action_entry_weight = float(training.get("v46_action_entry_weight", 0.5))
